mapper.select:
SELECT c.reg_id, c.p_reg_id, c.code, c.name,
	p.code AS p_code, p.name AS p_name
FROM tb_reg c
JOIN tb_reg p ON p.reg_id = c.p_reg_id


		AND p.code = #{parentCode}


		AND c.p_reg_id = #{parentRegId}


		AND c.code = #{code}


		AND c.name LIKE '%' || #{name} || '%'

	AND c.status = 'Y'

ORDER BY c.reg_id
